-- Additive staging migration. Fixed-price supplier records and route transitions remain simulated.
CREATE TABLE IF NOT EXISTS `managed_supply_records` (`id` VARCHAR(191) PRIMARY KEY,`seller_id` VARCHAR(191) NOT NULL,`product_id` VARCHAR(191) NOT NULL,`quantity_proposed` BIGINT NOT NULL,`quantity_accepted` BIGINT NULL,`agreed_unit_paisa` BIGINT NOT NULL,`accepted_total_paisa` BIGINT NULL,`status` VARCHAR(32) NOT NULL,`possession_status` VARCHAR(32) NOT NULL,`quality_status` VARCHAR(32) NOT NULL,`ownership_record_status` VARCHAR(32) NOT NULL,`risk_record_status` VARCHAR(32) NOT NULL,`evidence_reference` VARCHAR(191) NULL,`agreement_version` VARCHAR(191) NOT NULL,`agreement_language` VARCHAR(8) NOT NULL,`payout_beneficiary_reference` VARCHAR(191) NOT NULL,`simulation_label` VARCHAR(191) NOT NULL,`created_by` VARCHAR(191) NOT NULL,`decided_by` VARCHAR(191) NULL,`decision_reason` LONGTEXT NULL,`proposal_request_id` VARCHAR(191) NOT NULL UNIQUE,`decision_request_id` VARCHAR(191) NULL UNIQUE,`created_at` BIGINT NOT NULL,`decided_at` BIGINT NULL,KEY `idx_managed_supply_seller_status` (`seller_id`,`status`,`created_at`),FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`decided_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CHECK(`quantity_proposed`>0),CHECK(`agreed_unit_paisa`>0),CHECK(`status` IN ('proposed','accepted','rejected','cancelled')),CHECK(`decided_by` IS NULL OR `decided_by`<>`created_by`),CHECK(`status`<>'accepted' OR (`quantity_accepted`>0 AND `accepted_total_paisa`=`quantity_accepted`*`agreed_unit_paisa` AND `possession_status`='received' AND `quality_status`='accepted'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `managed_supplier_obligations` (`id` VARCHAR(191) PRIMARY KEY,`seller_id` VARCHAR(191) NOT NULL,`original_amount_paisa` BIGINT NOT NULL,`payout_beneficiary_reference` VARCHAR(191) NOT NULL,`agreement_version` VARCHAR(191) NOT NULL,`agreement_language` VARCHAR(8) NOT NULL,`status` VARCHAR(32) NOT NULL,`owed_at` BIGINT NOT NULL,`eligible_at` BIGINT NOT NULL,`created_at` BIGINT NOT NULL,FOREIGN KEY (`id`) REFERENCES `managed_supply_records`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles`(`id`) ON DELETE RESTRICT,CHECK(`original_amount_paisa`>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `managed_supplier_adjustments` (`id` VARCHAR(191) PRIMARY KEY,`obligation_id` VARCHAR(191) NOT NULL,`kind` VARCHAR(32) NOT NULL,`amount_paisa` BIGINT NOT NULL,`reason` LONGTEXT NOT NULL,`request_id` VARCHAR(191) NOT NULL UNIQUE,`created_by` VARCHAR(191) NOT NULL,`created_at` BIGINT NOT NULL,FOREIGN KEY (`obligation_id`) REFERENCES `managed_supplier_obligations`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CHECK(`amount_paisa`>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `managed_supplier_payments` (`id` VARCHAR(191) PRIMARY KEY,`obligation_id` VARCHAR(191) NOT NULL,`amount_paisa` BIGINT NOT NULL,`status` VARCHAR(32) NOT NULL,`destination_reference` VARCHAR(191) NOT NULL,`simulation_label` VARCHAR(191) NOT NULL,`prepared_by` VARCHAR(191) NOT NULL,`approved_by` VARCHAR(191) NULL,`request_id` VARCHAR(191) NOT NULL UNIQUE,`created_at` BIGINT NOT NULL,`updated_at` BIGINT NOT NULL,`paid_at` BIGINT NULL,KEY `idx_managed_supplier_payment_obligation` (`obligation_id`,`status`),FOREIGN KEY (`obligation_id`) REFERENCES `managed_supplier_obligations`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`prepared_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`approved_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CHECK(`amount_paisa`>0),CHECK(`approved_by` IS NULL OR `approved_by`<>`prepared_by`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `seller_route_transition_applications` (`id` VARCHAR(191) PRIMARY KEY,`seller_id` VARCHAR(191) NOT NULL,`from_route` VARCHAR(32) NOT NULL,`to_route` VARCHAR(32) NOT NULL,`status` VARCHAR(32) NOT NULL,`legal_name` VARCHAR(191) NOT NULL,`registration_authority` VARCHAR(191) NOT NULL,`registration_number` VARCHAR(191) NOT NULL,`tax_mode` VARCHAR(16) NOT NULL,`tax_registration_number` VARCHAR(191) NOT NULL,`evidence_references_json` LONGTEXT NOT NULL,`agreement_version` VARCHAR(191) NOT NULL,`agreement_language` VARCHAR(8) NOT NULL,`agreement_accepted_at` BIGINT NOT NULL,`requested_by` VARCHAR(191) NOT NULL,`reviewed_by` VARCHAR(191) NULL,`review_reason` LONGTEXT NULL,`effective_at` BIGINT NULL,`applied_at` BIGINT NULL,`request_id` VARCHAR(191) NOT NULL UNIQUE,`decision_request_id` VARCHAR(191) NULL UNIQUE,`version` BIGINT NOT NULL,`created_at` BIGINT NOT NULL,`updated_at` BIGINT NOT NULL,`open_seller_key` VARCHAR(191) GENERATED ALWAYS AS (CASE WHEN `status` IN ('submitted','under_review','changes_requested','scheduled') THEN `seller_id` ELSE NULL END) STORED,UNIQUE KEY `idx_seller_route_transition_open` (`open_seller_key`),KEY `idx_seller_route_transition_due` (`status`,`effective_at`),FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`requested_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`reviewed_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CHECK(`reviewed_by` IS NULL OR `reviewed_by`<>`requested_by`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `seller_agreement_acceptance_history` (`id` VARCHAR(191) PRIMARY KEY,`seller_id` VARCHAR(191) NOT NULL,`agreement_version` VARCHAR(191) NOT NULL,`language_presented` VARCHAR(8) NOT NULL,`commission_setting_version_id` VARCHAR(191) NULL,`commission_bps` BIGINT NOT NULL,`acceptance_request_id` VARCHAR(191) NOT NULL UNIQUE,`accepted_by` VARCHAR(191) NOT NULL,`accepted_at` BIGINT NOT NULL,`simulation_label` VARCHAR(191) NULL,UNIQUE KEY `idx_seller_agreement_acceptance_unique` (`seller_id`,`agreement_version`,`language_presented`,`commission_setting_version_id`),KEY `idx_seller_agreement_acceptance_current` (`seller_id`,`commission_setting_version_id`,`accepted_at`),FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`commission_setting_version_id`) REFERENCES `business_setting_versions`(`id`) ON DELETE RESTRICT,FOREIGN KEY (`accepted_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CHECK(`commission_bps` BETWEEN 0 AND 10000)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DROP TRIGGER IF EXISTS `managed_supplier_obligation_no_update`;
CREATE TRIGGER `managed_supplier_obligation_no_update` BEFORE UPDATE ON `managed_supplier_obligations` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Managed supplier obligation is immutable';
DROP TRIGGER IF EXISTS `managed_supplier_obligation_no_delete`;
CREATE TRIGGER `managed_supplier_obligation_no_delete` BEFORE DELETE ON `managed_supplier_obligations` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Managed supplier obligation is immutable';
DROP TRIGGER IF EXISTS `managed_supplier_adjustment_no_update`;
CREATE TRIGGER `managed_supplier_adjustment_no_update` BEFORE UPDATE ON `managed_supplier_adjustments` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Managed supplier adjustment is immutable';
DROP TRIGGER IF EXISTS `managed_supplier_adjustment_no_delete`;
CREATE TRIGGER `managed_supplier_adjustment_no_delete` BEFORE DELETE ON `managed_supplier_adjustments` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Managed supplier adjustment is immutable';
